list.query:
from(bucket: "smokeping") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "path_hop" and not exists r.trigger and r._field == "asn")
  |> group() |> distinct() |> sort() |> map(fn: (r) => ({_value: string(v: r._value)}))

targets.query:
import "join"
import "array"
import "regexp"
import "strings"
// join refuses an empty side (an empty range, the path meter off): each side
// gets one placeholder row that matches nothing real, dropped after the join.
pad = (tables=<-, row) => union(tables: [tables, array.from(rows: [row])])
// Destinations picked (pathmeter's base names), and the AS filter: only
// destinations whose recorded path crossed that AS in the range. Both are
// regular expressions on the target tag, so the filters stay in storage.
dest = regexp.compile(v: "^(?i)(${target:regex})$")
asSel = "${asn}"
crossing = if asSel == "any" then ".*" else strings.joinStr(v: "|", arr: from(bucket: "smokeping")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "path_hop" and not exists r.trigger and r._field == "asn")
  |> filter(fn: (r) => r._value == int(v: asSel)) |> group() |> distinct(column: "target")
  |> map(fn: (r) => ({_value: regexp.quoteMeta(v: r._value)}))
  |> findColumn(fn: (key) => true, column: "_value"))
along = regexp.compile(v: "^(?i)(" + crossing + ")$")
picked = (t) => t =~ dest and t =~ along
// What the exporter says about each target's host: its network (AS) and who
// runs it. Written on change only, so read back from the start; one row per
// base name (Google, Google_h2 and Google_tcp443 are one destination).
labels = from(bucket: "smokeping") |> range(start: time(v: 0), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "target_labels" and (r._field == "asn" or r._field == "operator" or r._field == "kind"))
  |> last() |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value") |> group()
  |> map(fn: (r) => ({destination: regexp.replaceAllString(r: /(_h[123]|_tcp(443)?|_icmp)$/, v: r.target, t: ""),
      asn: if exists r.asn then r.asn else 0,
      operator: if exists r.operator then r.operator else "unknown",
      kind: if exists r.kind then r.kind else "unknown"}))
  |> map(fn: (r) => ({r with key: strings.toLower(v: r.destination)}))
  |> sort(columns: ["destination"]) |> unique(column: "key")
  |> pad(row: {destination: "", asn: 0, operator: "", kind: "", key: ""})
// Who each network is: a destination's operator from its labels (Google),
// else the organization in the AS2Org name the path meter recorded with the
// hop ("HURRICANE - Hurricane Electric LLC, US" reads "Hurricane Electric
// LLC"). Traces recorded before the path meter wrote names leave the number.
recorded = from(bucket: "smokeping") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "path_hop" and not exists r.trigger and (r._field == "asn" or r._field == "as_name") and r.target =~ dest and r.target =~ along)
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => exists r.asn and exists r.as_name) |> group() |> unique(column: "asn")
  |> map(fn: (r) => ({asn: r.asn, rank: 1,
      name: regexp.replaceAllString(r: /, [A-Z][A-Z]$/, v: regexp.replaceAllString(r: /^[^ ]+ - /, v: r.as_name, t: ""), t: "")}))
names = union(tables: [labels |> filter(fn: (r) => r.asn > 0) |> sort(columns: ["operator"]) |> unique(column: "asn")
      |> map(fn: (r) => ({asn: r.asn, name: r.operator, rank: 0})), recorded])
  |> group() |> sort(columns: ["rank"]) |> unique(column: "asn") |> keep(columns: ["asn", "name"])
  |> pad(row: {asn: -2, name: ""})
// The last trace of each destination in the range.
last = from(bucket: "smokeping") |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "path_trace" and not exists r.trigger and (r._field == "as_path" or r._field == "hops" or r._field == "reached" or r._field == "dst") and r.target =~ dest and r.target =~ along)
  // One row per destination, even when its category changed in the range.
  |> group(columns: ["target", "_field"]) |> sort(columns: ["_time"]) |> last()
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value") |> group()
  |> map(fn: (r) => ({key: strings.toLower(v: r.target), destination: r.target, _time: r._time,
      as_path: if exists r.as_path then r.as_path else "", hops: r.hops, reached: r.reached, dst: r.dst}))
  |> pad(row: {key: "", destination: "", _time: time(v: 0), as_path: "", hops: 0, reached: false, dst: ""})
join.left(left: last, right: labels, on: (l, r) => l.key == r.key,
    as: (l, r) => {
      own = if exists r.asn and r.asn > 0 then string(v: r.asn) else ""
      return {destination: l.destination, network: if own != "" then "AS" + own + " " + r.operator else "not known",
        as_path: l.as_path,
        // Does the path the trace saw end in the destination's network?
        ends: if not l.reached then "not reached"
              else if own == "" or l.as_path == "" then "–"
              else if l.as_path == own or strings.hasSuffix(v: l.as_path, suffix: " " + own) then "yes"
              else "no",
        before: if own != "" and l.as_path == own then ""
                else if own != "" and strings.hasSuffix(v: l.as_path, suffix: " " + own) then strings.trimSuffix(v: l.as_path, suffix: " " + own)
                else l.as_path,
        hops: l.hops, dst: l.dst, _time: l._time}
    })
  |> filter(fn: (r) => r.destination != "")
  |> sort(columns: ["network", "destination"])
